    "«ვეფხისტყაოსანი» შოთა რუსთაველის გენიალური პოემაა.",
    "ქართულ ენაში არ არსებობს გრამატიკული სქესი.",
    "ქართული ღვინის დაყენების 8000-წლიანი ტრადიცია აქვს ქვევრში.",
    "სიტყვა «მადლობა» მადლის გაცემას ნიშნავს.",
    "ქართული მრავალხმიანობა იუნესკოს მიერ აღიარებულია.",
    "«ხინკალი» და «ჭაშუშული» ქართული სამზარეულოს ნაწილია.",
    "თბილისი დაარსდა V საუკუნეში ვახტანგ გორგასლის მიერ.",
    "სიტყვა «მშვიდობა» მშვიდ მდგომარეობას ნიშნავს.",
    "ქართული ენა უძველესი მწერლობის ენაა კავკასიაში.",
    "«ხაჭაპური» ქართული ეროვნული კერძია.",
    "სიტყვა «მეგობარი» «ეგოს» (იმავე) արմատიდან მოდის.",
